package com.sakalti.modifier;
import net.minecraft.entity.ItemEntity; import net.minecraft.entity.LivingEntity; import net.minecraft.world.World; import net.minecraft.util.math.Vec3d; import net.minecraft.item.ItemStack;
import slimeknights.tconstruct.library.modifiers.Modifier; import slimeknights.tconstruct.library.tools.nbt.IToolStackView;
public class SuperMagnetModifier extends Modifier { @Override public void onInventoryTick(IToolStackView tool,int level,World world,LivingEntity e,int slot,boolean selected,boolean correct,ItemStack stack){if(world==null||world.isClient||e==null||!correct)return;for(ItemEntity item:world.getEntitiesByClass(ItemEntity.class,e.getBoundingBox().expand(6),x->x.getPickupDelay() <= 0)){Vec3d d=e.getPos().add(0,e.getEyeHeight()/2.0,0).subtract(item.getPos());double len=d.length();if(len>0.5&&len<6){double s=0.5*level/len;item.setVelocity(item.getVelocity().add(d.scale(s)));}}}}
